// Checks lessons against the rules in AGENTS.md. No browser needed.
// Usage:  bun tools/lesson-check.js              (all modules: the progress report)
//         bun tools/lesson-check.js foundations  (one or more module ids)
//         bun tools/lesson-check.js foundations -v   (also show warnings)
// Exit code 1 if any checked lesson fails. Do not edit this file to make a lesson pass.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const args = process.argv.slice(2);
const verbose = args.includes('-v');
const only = args.filter(a => !a.startsWith('-'));

/* ---------- load every module with a small fake SDA ---------- */
const stub = new Proxy(function () {}, {
  get: (t, k) => (k === Symbol.toPrimitive ? () => '' : k === 'then' ? undefined : stub),
  apply: () => stub, construct: () => stub, set: () => true,
});
const soft = obj => new Proxy(obj, { get: (t, k) => (k in t ? t[k] : stub), set: (t, k, v) => ((t[k] = v), true) });
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const dedent = s => String(s).replace(/^\n/, '');
const h = {
  code: (lang, src, title) => `<div class="code"><pre>${esc(src)}</pre></div>`,
  callout: (kind, title, body) => `<div class="callout ${kind}"><b class="ct">${title}</b>${body}</div>`,
  deep: x => `<div class="deep-only">${x}</div>`,
  simple: x => `<div class="simple-only">${x}</div>`,
  tier: t => `<span class="tier ${t}">${t}</span>`,
  table: (head, rows) => `<div class="tbl-wrap"><table class="tbl"><thead><tr>${head.map(x => `<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,
  math: s => `<div class="math">${esc(dedent(s))}</div>`,
  list: items => `<ul>${items.map(i => `<li>${i}</li>`).join('')}</ul>`,
};
const u = soft({ esc, dedent, clamp: (v, a, b) => Math.max(a, Math.min(b, v)), lerp: (a, b, t) => a + (b - a) * t,
  slug: s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-'), shuffle: a => a, stripHtml: s => String(s).replace(/<[^>]+>/g, ''),
  fmtNum: n => String(n), fmtBytes: n => String(n), fmtDur: n => String(n) });
const modules = [];
const SDA = soft({ h, u, register: d => { if (d && d.kind === 'module') modules.push(d); } });
const win = soft({ SDA });
const dir = path.join(root, 'js/modules');
for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.js')).sort()) {
  const before = modules.length;
  const origError = console.error; console.error = () => {};
  try { new Function('window', 'document', 'SDA', fs.readFileSync(path.join(dir, f), 'utf8'))(win, stub, SDA); }
  catch (e) { console.error = origError; console.log(`ERROR ${f}: ${e.message}`); process.exitCode = 1; }
  console.error = origError;
  if (modules.length === before) { console.log(`ERROR ${f}: no module registered`); process.exitCode = 1; }
  else modules[modules.length - 1].file = f;
}
modules.sort((a, b) => (a.order || 99) - (b.order || 99));
const order = Object.fromEntries(modules.map((m, i) => [m.id, i + 1]));

/* ---------- text helpers ---------- */
const decode = s => s.replace(/&nbsp;/g, ' ').replace(/&[a-z]+;|&#\d+;/gi, ' ');
const noCode = s => String(s || '').replace(/<pre[\s\S]*?<\/pre>|<code[\s\S]*?<\/code>|<div class="math">[\s\S]*?<\/div>/g, ' ');
const prose = s => decode(noCode(s).replace(/<[^>]+>/g, ' '));
const words = s => prose(s).split(/\s+/).filter(Boolean).length;
// list items, table cells, headings and paragraphs end a sentence even without a full stop
const sentences = s => decode(noCode(s).replace(/<\/?(li|td|th|h\d|p|tr|ul|ol|div|table)\b[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' '))
  .split(/(?<=[.!?])\s+|\n/).map(x => x.trim()).filter(x => /[a-z]/i.test(x));
function strings(v, where, out) { // every string inside a value, with a label for messages
  if (typeof v === 'string') out.push([where, v]);
  else if (Array.isArray(v)) v.forEach((x, i) => strings(x, `${where}[${i}]`, out));
  else if (v && typeof v === 'object') for (const k in v) strings(v[k], where ? `${where}.${k}` : k, out);
  return out;
}

/* ---------- later topics (AGENTS.md section 5) ---------- */
// [pattern, module id that teaches it, optional lesson id inside that module]
const TOPICS = [
  [/\bp9[59](\.9)?\b|percentile/i, 'foundations', 'percentiles-tail-latency'],
  [/\bSL[OA]s?\b|error budget/i, 'foundations', 'sli-slo-sla'],
  [/single point of failure|\bSPOF/i, 'foundations', 'fault-tolerance-spof'],
  [/microservice|\bmonolith/i, 'foundations', 'monolith-to-microservices'],
  [/\bDNS\b/, 'networking'], [/\bTLS\b|\bHTTPS\b/, 'networking'], [/\bgRPC\b|GraphQL/, 'networking'], [/WebSocket/i, 'networking'], [/idempoten/i, 'networking'],
  [/load balanc/i, 'traffic'], [/\bCDN/, 'traffic'], [/rate limit/i, 'traffic'], [/\bDDoS/, 'traffic'],
  [/(?<!\b(L[123]|CPU|hardware|processor|disk|page|browser)[ -])\bcach(e|es|ing)\b/i, 'caching'], [/\bRedis\b|Memcached/, 'caching'],
  [/\bshard/i, 'databases'], [/\breplica(s|tion)?\b/i, 'databases'], [/consistent hashing/i, 'databases'], [/\bNoSQL\b/, 'databases'],
  [/\bCAP\b|PACELC/, 'distributed'], [/\bquorum/i, 'distributed'], [/\bRaft\b|\bPaxos\b/, 'distributed'], [/two-phase commit|\b2PC\b/i, 'distributed'], [/\bsagas?\b/i, 'distributed'], [/\bCRDT/, 'distributed'],
  [/\bKafka\b|RabbitMQ|\bSQS\b/, 'async'], [/message queue|message broker|pub\/sub/i, 'async'], [/\bCDC\b|change data capture/i, 'async'],
  [/Elasticsearch|inverted index/i, 'search'], [/bloom filter/i, 'search'], [/\btrie\b/i, 'search'],
  [/circuit breaker/i, 'reliability'], [/bulkhead/i, 'reliability'], [/autoscal/i, 'reliability'], [/chaos (engineering|monkey)/i, 'reliability'],
  [/Kubernetes|\bk8s\b/i, 'architecture'], [/\bDocker\b/, 'architecture'], [/service mesh|sidecar/i, 'architecture'], [/serverless/i, 'architecture'],
  [/\bOAuth|\bOIDC\b/, 'security'], [/\bJWT/, 'security'],
  [/WebRTC/, 'realtime'],
];
const PREVIEW = /you(’|')?ll learn|you will learn|later (in|lesson|module)|\b(Module|Lesson) \d+/i;

/* ---------- the checks ---------- */
function checkLesson(l, m, li) {
  const fail = [], warn = [];
  const how = l.how || {};
  const summaryWords = words(l.summary);
  if (!l.summary) fail.push('summary missing');
  else if (summaryWords > 40) fail.push(`summary is ${summaryWords} words (max 40)`);
  if (/^\s*in short/i.test(prose(l.summary))) fail.push('summary starts with "In short" (the app already adds it)');
  if (!/<h3>\s*A small example\s*<\/h3>/i.test(l.problem || '')) fail.push('problem has no <h3>A small example</h3>');
  if (!/<ul>/.test(l.problem || '')) fail.push('problem has no bullet list (<ul>)');
  const steps = how.steps || [];
  if (!(steps.length >= 3 && steps.length <= 6)) fail.push(`how.steps has ${steps.length} steps (need 3 to 6)`);
  steps.forEach((s, i) => {
    if (!s || typeof s !== 'object' || !s.icon || !s.title || !s.text) fail.push(`how.steps[${i}] needs icon, title and text`);
    else if (sentences(s.text).length > 2) fail.push(`how.steps[${i}] text has ${sentences(s.text).length} sentences (max 2)`);
  });
  const html = how.html || '';
  if (!/class="tbl"/.test(html)) fail.push('how.html has no table');
  if (!/Important point/i.test(html)) fail.push('how.html has no "Important point" box');
  if (!/<h3>\s*(How we handle it|When to use which)\s*<\/h3>/i.test(html)) fail.push('how.html has no "How we handle it" or "When to use which" heading');
  if (!how.deep && !l.deep) fail.push('no Go deeper content (how.deep)');
  const simple = [l.summary, l.problem, how.intro, ...steps.map(s => s && typeof s === 'object' ? `${s.title}. ${s.text}` : s), html].join(' ');
  const simpleWords = words(simple);
  if (simpleWords > 400) fail.push(`simple part is ${simpleWords} words (max about 400)`);
  sentences(simple).filter(s => s.split(/\s+/).length > 25).forEach(s => warn.push(`long sentence: "${s.slice(0, 60)}…"`));

  const all = strings(l, '', []);
  const emDash = all.filter(([, s]) => s.includes('—')).map(([w]) => w);
  if (emDash.length) fail.push(`em dash (—) in ${emDash.slice(0, 4).join(', ')}${emDash.length > 4 ? ' …' : ''}`);
  const links = all.filter(([, s]) => /<a\s[^>]*href|https?:\/\//i.test(s)).map(([w]) => w);
  if (links.length) fail.push(`link in ${links.slice(0, 4).join(', ')}`);
  const semis = all.reduce((n, [, s]) => n + (prose(s).match(/;/g) || []).length, 0);
  if (semis > 2) fail.push(`${semis} semicolons (max 2)`);
  fail.push(...topicProblems(all, m, li));
  return { fail, warn, simpleWords };
}

// Fields that are names or labels, not teaching text.
const NOT_TEXT = /(^|\.)(tags|type|id|icon|src|sources|co|pg|lab)(\[\d+\])?(\.|$)/;
// all: [where, text] pairs that form one group (a lesson, or one quiz question).
// A later topic is fine if at least one string in the group previews it ("you will learn ...").
function topicProblems(all, m, li) {
  all = all.filter(([w]) => !NOT_TEXT.test(w));
  const out = [];
  for (const [rx, mod, lessonId] of TOPICS) {
    const teach = order[mod]; const here = order[m.id];
    let early = here < teach;
    if (!early && mod === m.id && lessonId) {
      const ti = m.lessons.findIndex(x => x.id === lessonId);
      early = li >= 0 && ti >= 0 && li < ti;
    }
    if (!early) continue;
    const withTerm = all.filter(([, s]) => rx.test(prose(s)));
    if (withTerm.some(([, s]) => PREVIEW.test(prose(s)))) continue;
    const hits = withTerm.map(([w]) => w);
    if (hits.length) out.push(`"${prose(all.find(([w]) => w === hits[0])[1]).match(rx)[0]}" is taught later (${lessonId || mod}) with no "you will learn" preview, in ${hits.slice(0, 3).join(', ')}`);
  }
  return out;
}

/* ---------- lesson ids must not change ---------- */
const idsFile = path.join(__dirname, 'lesson-ids.json');
const savedIds = fs.existsSync(idsFile) ? JSON.parse(fs.readFileSync(idsFile, 'utf8')) : {};
const idProblems = [];
for (const [mod, ids] of Object.entries(savedIds)) {
  if (only.length && !only.includes(mod)) continue;
  const m = modules.find(x => x.id === mod);
  const now = new Set(((m && m.lessons) || []).map(l => l.id));
  ids.filter(id => !now.has(id)).forEach(id => idProblems.push(`lesson id "${id}" is missing from module ${mod} (renamed or removed)`));
}

/* ---------- report ---------- */
const unknown = only.filter(id => !order[id]);
if (unknown.length) { console.log(`Unknown module id: ${unknown.join(', ')}. Known: ${modules.map(m => m.id).join(', ')}`); process.exit(1); }
let pass = 0, failN = 0;
for (const m of modules) {
  if (only.length && !only.includes(m.id)) continue;
  let mp = 0;
  const lines = [];
  (m.lessons || []).forEach((l, i) => {
    const r = checkLesson(l, m, i);
    if (r.fail.length) { failN++; lines.push(`  FAIL ${l.id} (${r.simpleWords} words)\n${r.fail.map(x => `       - ${x}`).join('\n')}`); }
    else { pass++; mp++; lines.push(`  PASS ${l.id} (${r.simpleWords} words)`); }
    if (verbose && r.warn.length) lines.push(r.warn.map(x => `       ~ ${x}`).join('\n'));
  });
  const quizText = strings({ quiz: m.quiz, cheatsheet: m.cheatsheet }, '', []);
  const mfail = [];
  const qd = quizText.filter(([, s]) => s.includes('—')).length;
  if (qd) mfail.push(`em dash (—) in ${qd} quiz/cheatsheet strings`);
  const ql = quizText.filter(([, s]) => /<a\s[^>]*href|https?:\/\//i.test(s)).length;
  if (ql) mfail.push(`link in ${ql} quiz/cheatsheet strings`);
  (m.quiz || []).forEach((q, i) => mfail.push(...topicProblems(strings(q, `quiz[${i}]`, []), m, (m.lessons || []).length)));
  console.log(`\n${m.id} (${m.file}): ${mp}/${(m.lessons || []).length} lessons pass`);
  console.log(lines.join('\n'));
  if (mfail.length) { failN++; console.log(`  FAIL module quiz/cheatsheet\n${mfail.map(x => `       - ${x}`).join('\n')}`); }
}
idProblems.forEach(p => { failN++; console.log(`FAIL ${p}`); });
console.log(`\nTotal: ${pass} lessons pass, ${failN} problems.`);
if (failN) process.exitCode = 1;
